/*
 * Host tests for pico_decode.c. Every vector comes from the Python oracle via
 * vectors.h (generated by gen_vectors.py). No GPIO, no radio, no Zigbee.
 *
 *   make -C firmware/pico_bridge/test
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "../main/pico_decode.h"
#include "vectors.h"

static int s_fails;

#define CHECK(cond, ...)                                  \
    do {                                                  \
        if (cond) {                                       \
            printf("PASS ");                              \
        } else {                                          \
            printf("FAIL ");                              \
            s_fails++;                                    \
        }                                                 \
        printf(__VA_ARGS__);                              \
        printf("\n");                                     \
    } while (0)

static size_t unhex(const char *hex, uint8_t *out, size_t cap)
{
    size_t n = strlen(hex) / 2;
    if (n > cap) {
        n = cap;
    }
    for (size_t i = 0; i < n; i++) {
        unsigned v;
        sscanf(hex + 2 * i, "%2x", &v);
        out[i] = (uint8_t)v;
    }
    return n;
}

static void hexstr(const uint8_t *b, size_t n, char *out)
{
    for (size_t i = 0; i < n; i++) {
        sprintf(out + 2 * i, "%02x", b[i]);
    }
    out[2 * n] = 0;
}

static size_t bits_from_str(const char *s, uint8_t *out, size_t cap)
{
    size_t n = strlen(s);
    if (n > cap) {
        n = cap;
    }
    for (size_t i = 0; i < n; i++) {
        out[i] = (uint8_t)(s[i] == '1');
    }
    return n;
}

static pico_frame_t make_frame(int ms, const char *hex)
{
    pico_frame_t f;
    memset(&f, 0, sizeof f);
    f.len = (uint8_t)unhex(hex, f.body, sizeof f.body);
    f.crc_ok = true;
    f.t_us = (int64_t)ms * 1000;
    return f;
}

static bool body_crc_ok(const uint8_t *b, size_t n)
{
    return n >= 3 && pico_crc16(b, n - 2) == (uint16_t)((b[n - 2] << 8) | b[n - 1]);
}

static void test_crc(void)
{
    for (size_t i = 0; i < sizeof k_published / sizeof k_published[0]; i++) {
        uint8_t b[PICO_BODY_MAX];
        size_t n = unhex(k_published[i].hex, b, sizeof b);
        CHECK(body_crc_ok(b, n), "crc %s", k_published[i].name);
    }
    for (size_t i = 0; i < sizeof k_setlevel / sizeof k_setlevel[0]; i++) {
        uint8_t b[PICO_BODY_MAX];
        size_t n = unhex(k_setlevel[i].hex, b, sizeof b);
        CHECK(body_crc_ok(b, n), "crc set-level %s", k_setlevel[i].name);
    }
}

static void test_fixtures(void)
{
    size_t nfix = sizeof k_fixtures / sizeof k_fixtures[0];
    CHECK(nfix == 9, "nine fixtures (have %zu)", nfix);
    for (size_t i = 0; i < nfix; i++) {
        uint8_t bits[1024];
        size_t nb = bits_from_str(k_fixtures[i].bits, bits, sizeof bits);
        pico_frame_t fr;
        bool ok = pico_decode_bits(bits, nb, false, &fr);
        char hex[PICO_BODY_MAX * 2 + 1] = "";
        if (ok) {
            hexstr(fr.body, fr.len, hex);
        }
        CHECK(ok && fr.crc_ok && strcmp(hex, k_fixtures[i].hex) == 0, "fixture %.8s", k_fixtures[i].hex);

        /* The air polarity can be inverted. Both must decode. */
        uint8_t inv[1024];
        for (size_t j = 0; j < nb; j++) {
            inv[j] = bits[j] ^ 1;
        }
        pico_frame_t fi;
        bool oki = pico_decode_bits(inv, nb, false, &fi);
        CHECK(oki && fi.len == fr.len && memcmp(fi.body, fr.body, fr.len) == 0, "fixture %.8s inverted polarity",
              k_fixtures[i].hex);

        if (k_fixtures[i].hex[0] == '9' && k_fixtures[i].hex[1] == '3') {
            CHECK(pico_action_of(fr.body[0]) == PICO_ACT_OTHER && !pico_is_set_level(fr.body, fr.len),
                  "fixture %.8s is a beacon: other, not set-level", k_fixtures[i].hex);
        }
    }

    /* Noise and truncated bursts must not produce a frame. */
    uint8_t noise[400];
    unsigned s = 12345;
    for (size_t i = 0; i < sizeof noise; i++) {
        s = s * 1103515245u + 12345u;
        noise[i] = (s >> 16) & 1;
    }
    pico_frame_t fr;
    CHECK(!pico_decode_bits(noise, sizeof noise, false, &fr), "random bits decode to nothing");
    uint8_t bits[1024];
    size_t nb = bits_from_str(k_fixtures[0].bits, bits, sizeof bits);
    CHECK(!pico_decode_bits(bits, nb / 2, false, &fr), "half a burst decodes to nothing");

    /* Single-bit damage. CRC-16 catches every one-bit error, so a flip may never yield a
     * different CRC-good frame. It either leaves the original frame (preamble/tail bits),
     * breaks the 8N1 framing (no frame), or leaves a CRC-bad candidate that keep_fail reports. */
    pico_frame_t orig;
    pico_decode_bits(bits, nb, false, &orig);
    unsigned wrong = 0, bad_candidates = 0;
    for (size_t j = 0; j < nb; j++) {
        uint8_t flipped[1024];
        memcpy(flipped, bits, nb);
        flipped[j] ^= 1;
        pico_frame_t ff;
        memset(&ff, 0, sizeof ff);
        bool okf = pico_decode_bits(flipped, nb, true, &ff);
        if (okf && (ff.len != orig.len || memcmp(ff.body, orig.body, orig.len) != 0)) {
            wrong++;
        }
        if (!okf && ff.len > 0 && !ff.crc_ok) {
            bad_candidates++;
        }
    }
    CHECK(wrong == 0, "no single-bit flip produces a different CRC-good frame");
    CHECK(bad_candidates >= 100, "single-bit flips in the payload yield CRC-bad candidates (%u)", bad_candidates);
}

static void test_fields(void)
{
    uint8_t b[PICO_BODY_MAX];
    size_t n = unhex("8a0002dd0abf210403000200ccccccccccccccccccccadcf", b, sizeof b);
    char serial[9], button[16];
    pico_serial_str(b, n, serial);
    pico_button_str(b, n, button, sizeof button);
    CHECK(strcmp(serial, "02dd0abf") == 0 && pico_serial_u32(b, n) == 0x02dd0abfu, "serial of spare Pico");
    CHECK(strcmp(button, "on") == 0 && pico_action_of(b[0]) == PICO_ACT_PRESS, "button on, action press");

    for (size_t i = 0; i < sizeof k_setlevel / sizeof k_setlevel[0]; i++) {
        uint8_t s[PICO_BODY_MAX];
        size_t sn = unhex(k_setlevel[i].hex, s, sizeof s);
        pico_serial_str(s, sn, serial);
        pico_button_str(s, sn, button, sizeof button);
        CHECK(pico_is_set_level(s, sn) && strcmp(serial, "033ca7a6") == 0 && strcmp(button, k_setlevel[i].percent) == 0 &&
                  pico_level_word(s) == k_setlevel[i].word && pico_fade_ms(s) == 250,
              "set-level %s: dimmer 033ca7a6 level %s", k_setlevel[i].name, k_setlevel[i].percent);
    }

    n = unhex("9343a3916f00210c00ffffffffff0802916f1a02cccc5b47", b, sizeof b);
    pico_serial_str(b, n, serial);
    pico_button_str(b, n, button, sizeof button);
    CHECK(!pico_is_set_level(b, n) && strcmp(serial, "a3916f00") == 0 && strcmp(button, "-") == 0 &&
              pico_action_of(b[0]) == PICO_ACT_OTHER,
          "bridge beacon stays other");
}

static void test_scenarios(void)
{
    for (size_t si = 0; si < sizeof k_scenarios / sizeof k_scenarios[0]; si++) {
        const vec_scenario_t *sc = &k_scenarios[si];
        pico_grouper_t g;
        pico_grouper_init(&g);
        char got[16][512];
        size_t ngot = 0;
        unsigned new_groups = 0;
        for (size_t i = 0; i < sc->nframes; i++) {
            pico_frame_t fr = make_frame(sc->frames[i].ms, sc->frames[i].hex);
            pico_event_t closed;
            pico_add_result_t r = pico_grouper_add(&g, &fr, &closed);
            if (r.new_group) {
                new_groups++;
            }
            if (r.closed && ngot < 16) {
                pico_format_event(got[ngot++], sizeof got[0], &closed);
            }
        }
        pico_event_t last;
        if (pico_grouper_flush(&g, &last) && ngot < 16) {
            pico_format_event(got[ngot++], sizeof got[0], &last);
        }
        bool ok = ngot == sc->nlines && new_groups == sc->nlines;
        for (size_t i = 0; ok && i < ngot; i++) {
            ok = strcmp(got[i], sc->lines[i]) == 0;
            if (!ok) {
                printf("  want: %s\n  got:  %s\n", sc->lines[i], got[i]);
            }
        }
        CHECK(ok, "scenario '%s': %zu event(s), one send per group, lines match oracle", sc->name, sc->nlines);
    }
}

static void test_doc_line(void)
{
    /* The example line in the design doc, from the first captured fixture at t=0. */
    uint8_t bits[1024];
    size_t nb = bits_from_str(k_fixtures[0].bits, bits, sizeof bits);
    pico_frame_t fr;
    bool ok = pico_decode_bits(bits, nb, false, &fr);
    fr.t_us = 0;
    pico_grouper_t g;
    pico_grouper_init(&g);
    pico_event_t ev;
    pico_grouper_add(&g, &fr, &ev);
    pico_grouper_flush(&g, &ev);
    char line[512];
    pico_format_event(line, sizeof line, &ev);
    const char *want =
        "t=0.000s serial=02dd0abf button=on action=press seq=00 seqs=00 repeats=1 crc=ok "
        "frame=8a 00 02 dd 0a bf 21 04 03 00 02 00 cc cc cc cc cc cc cc cc cc cc ad cf";
    CHECK(ok && strcmp(line, want) == 0, "design-doc example line");
}

int main(void)
{
    test_crc();
    test_fixtures();
    test_fields();
    test_scenarios();
    test_doc_line();
    if (s_fails) {
        printf("DECODE TESTS FAILED (%d)\n", s_fails);
        return 1;
    }
    printf("DECODE TESTS PASSED\n");
    return 0;
}
